/* CALR · intl 分卷 mm-p04（由 _work/merge/build-packs.js 从 prototype/data/laws/ 自动生成，请勿手工编辑） */
(function (root) {
  'use strict';
  var FT = root.CALR_FULLTEXT = root.CALR_FULLTEXT || {};
  FT["MM-H067"] = {"id":"MM-H067","coverage":"full","language":"zh","sourceName":"缅甸官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":32,"structureMode":"ARTICLE","title":{"zh":"旅馆和旅游法 1993","en":"Hotels and Tourism Law 1993","orig":"旅馆和旅游法 1993","vi":"Luật Khách sạn và Du lịch năm 1993","th":"พระราชบัญญัติโรงแรมและการท่องเที่ยว ค.ศ. 1993","id":"Undang-Undang Perhotelan dan Pariwisata Tahun 1993","ms":"Akta Hotel dan Pelancongan 1993"},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"缅甸官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"MM","countryName":"缅甸","layer":"intl","articles":[{"id":"MM-H067-A1","no":1,"noLabel":{"zh":"第1条"},"chapter":{"zh":"第二章"},"text":{"zh":"缅甸旅馆和旅游法 1993 年 10 月 23 日第一章 名称与定义\n本法称为《缅甸旅馆和旅游法》。"}},{"id":"MM-H067-A2","no":2,"noLabel":{"zh":"第2条"},"chapter":{"zh":"第二章"},"text":{"zh":"本法中的词语定义如下：\n1、旅馆：是指供旅客住宿，分各种客房数量、等级并提供餐饮及各种服务的经营企业。其中包括饭店和宾馆；\n2、旅馆业：包括为外国旅客旅游活动提供安排和服务的企业、 旅游代理机构、旅游用车及导游服务；\n3、旅游业：包括为外国旅客旅游活动提供安排和服务的企业、 旅游代理机构、旅游用车及导游服务；\n4、外国旅客：是指外国旅客和外宾；\n5、旅馆和旅游业：是指上述饭店、旅馆业以及旅游业务；\n6、执照：是指旅馆和旅游局颁发的可以经营旅馆及旅游业的证件；\n7、部：是指旅馆和旅游部；\n8、部长：是指旅馆和旅游部长；\n9、局：是指旅馆和旅游局；\n10、检查组：是指由局组建的负责检查旅馆和旅游业的小组。\n第二章 宗旨"}},{"id":"MM-H067-A3","no":3,"noLabel":{"zh":"第3条"},"chapter":{"zh":"第三章"},"text":{"zh":"本法律的宗旨\n1、使旅游业得到有计划的发展；\n2、使旅客了解缅甸的优秀文化，秀丽的自然风光；\n3、避免因旅游业使缅甸的优秀文化及自然风光蒙受破坏；\n4、通过旅游业的发展增进同世界各国的友谊和了解；\n5、通过提高旅游业务水平增加就业率；\n6、使旅客得到安全和满意。\n第三章 关于旅馆及旅游业领导委员会的组建及职责"}},{"id":"MM-H067-A4","no":4,"noLabel":{"zh":"第4条"},"chapter":{"zh":"第三章"},"text":{"zh":"政府必须成立由下列人士组成的旅馆和旅游业领导委员会：\n1、部长——主席\n2、有关政府部门及团体的代表——成员\n3、受主席委托者——秘书长\n（1）如有需要，旅馆和旅游业领导委员会可设立副主席和副秘书长；\n（2）可根据需要改组旅馆和旅游业领导委员会。"}},{"id":"MM-H067-A5","no":5,"noLabel":{"zh":"第5条"},"chapter":{"zh":"第四章"},"text":{"zh":"旅馆和旅游业领导委员会具有以下职责：\n1、按照本法的宗旨制定旅馆及旅游业的方针政策；\n2、指导旅馆和旅游业有计划的发展；\n3、指导旅馆和旅游业与各国的联系；\n4、指导旅馆和旅游业服务质量的业务水平的提高。\n第四章 部的职责"}},{"id":"MM-H067-A6","no":6,"noLabel":{"zh":"第6条"},"chapter":{"zh":"第五章"},"text":{"zh":"部的职责\n1、依照本法规的宗旨监督局的工作；\n2、具体落实发展与旅馆和旅游业有关的各个国家、国际组织、 其他团体和个人的联系；\n3、发展与旅馆和旅游业有关的各个国家、国际组织、其他团体和个人的联系；\n4、为发展和提高旅馆和旅游业的服务质量和业务水平，举办各种研讨会、论文交流会及展览会；\n5、有权批准、修改或拒绝欲从事旅馆业者提出的意向性申请；\n6、对每个旅馆、旅馆业的类别、级别及所需设施作出规定；\n7、对旅游业的类别及所需设施作出规定；\n8、制定必要的计划和安排，以促进外国旅客了解缅甸的兴趣并到缅甸进行研究；\n9、对旅游地区作出规定；\n10、与有关政府部门和团体进行磋商，以方便外国旅客办理入境签证延期手续；\n11、与有关部门和团体进行磋商，在省、县及有关城镇成立旅馆和旅游业监督小组，并规定其职责范围；\n12、对执照费、执照更新费、执照罚款额及旅馆和旅游业税额作出规定；\n13、适时向政府报告旅馆和旅游业工作及发展情况。\n第五章 局的职责范围"}},{"id":"MM-H067-A7","no":7,"noLabel":{"zh":"第7条"},"chapter":{"zh":"第六章"},"text":{"zh":"局的职责：\n1、执行旅馆和旅游业领导委员会及部制定的政策和指示；\n2、为了便于审核执照的申请事项，成立执照审核小组，并规定其职责范围；\n3、有权发放或拒绝发放执照，限期收回执照或废除执照；\n4、制定有关执照的规定；\n5、开设培训班，以提高旅馆和旅游业的服务质量和业务水平；\n6、为便于检查旅馆和旅游业的情况，成立检查组并规定其职责范围；\n7、监督旅馆和旅游业的各项业务；\n8、对执照执有者提出的对旅馆及旅游业监督小组的工作不满作出决定；\n9、对于没有按照本法令规定缴纳税款的，必须按有关的规定征收税款。\n第六章 意向性申请"}},{"id":"MM-H067-A8","no":8,"noLabel":{"zh":"第8条"},"chapter":{"zh":"第六章"},"text":{"zh":"凡欲从事旅馆业的政府部门、政府团体或与政府部门合资的团体、 繁荣协会、合作社以及其他团体或个人，必须按照规定，在没有开始经营以前，向部提出意向性申请。"}},{"id":"MM-H067-A9","no":9,"noLabel":{"zh":"第9条"},"chapter":{"zh":"第六章"},"text":{"zh":"如果在本法颁布之时，正在修建或装修房屋建筑准备从事旅馆业的政府部门和团体、与政府部门合作的团体、繁荣协会、合作社以及其他团体或个人，须在规定期限内向部报告计划安排并提出申请。"}},{"id":"MM-H067-A10","no":10,"noLabel":{"zh":"第10条"},"chapter":{"zh":"第六章"},"text":{"zh":"如果在本法规发布以前已经在从事旅馆业的政府部门和团体、与政府部门合资的团体、繁荣协会、合作社以及其他团体或个人， 无须向部提出申请。"}},{"id":"MM-H067-A11","no":11,"noLabel":{"zh":"第11条"},"chapter":{"zh":"第七章"},"text":{"zh":"部\n1、按照第八条或第九条规定，从下面几个方面对欲从事旅馆业的申请者进行审核：\n（1）是否符合本法规的宗旨；\n（2）是否有利于将来的计划；\n（3）旅馆与旅游业是否适应当地所能提供的服务。\n2、按照第一款规定进行审核后，对计划安排作出同意、修改或不同意的决定。\n第七章 执照的申请"}},{"id":"MM-H067-A12","no":12,"noLabel":{"zh":"第12条"},"chapter":{"zh":"第七章"},"text":{"zh":"根据第十一条规定，得到部的批准的，必须按照规定手续向局申请旅馆或旅馆业执照。"}},{"id":"MM-H067-A13","no":13,"noLabel":{"zh":"第13条"},"chapter":{"zh":"第七章"},"text":{"zh":"经营旅馆业者，尽管已根据现行某项法律规定履行手续，但只要是为外国旅馆或同时为国内外旅客提供服务者，都必须依照本法规定申请执照。"}},{"id":"MM-H067-A14","no":14,"noLabel":{"zh":"第14条"},"chapter":{"zh":"第七章"},"text":{"zh":"在本法律公布以前，已经在从事旅馆和旅馆业的政府部门和团体、 与政府合营的团体、繁荣协会、合作社组织、其他团体或人士， 如果还没有依照缅甸旅游法获得执照，必须按规定手续向局申请执照。"}},{"id":"MM-H067-A15","no":15,"noLabel":{"zh":"第15条"},"chapter":{"zh":"第七章"},"text":{"zh":"凡愿经营某项旅游业者必须按规定手续向局申请执照。"}},{"id":"MM-H067-A16","no":16,"noLabel":{"zh":"第16条"},"chapter":{"zh":"第八章"},"text":{"zh":"局对为从事旅馆和旅游业某项业务而提出的执照申请，必须审查其是否具备规定条件：\n1、如符合者准予发放执照；\n2、如不符合，将拒发执照。\n第八章 执照持有者的义务"}},{"id":"MM-H067-A17","no":17,"noLabel":{"zh":"第17条"},"chapter":{"zh":"第八章"},"text":{"zh":"执照持有者：\n1、只能从事执照规定的业务项目；\n2、必须按规定用缅币或外币交纳执照费及旅馆旅游业税款；\n3、必须遵守执照所规定的纪律；\n4、必须接受旅馆和旅游业监督小组和检查小组的检查；\n5、必须按规定送交局制定的报表；\n6、如执照到期并愿继续经营者必须按规定申请执照延期；\n7、必须遵守部或局按具体情况发布的命令或指示。"}},{"id":"MM-H067-A18","no":18,"noLabel":{"zh":"第18条"},"chapter":{"zh":"第九章"},"text":{"zh":"1、执照持有者如需更改委托执行者，必须把更改情况以书面形式通知局；\n2、执照持有者或受执照持有者委托的经营者，如更改经营地点， 必须把更改情况用书面形式通知局；\n3、如果在执照满期以前执照持有者死亡，其合法继承者必须按规定向局申请报告。\n第九章 执照的收回、吊销与作废"}},{"id":"MM-H067-A19","no":19,"noLabel":{"zh":"第19条"},"chapter":{"zh":"第九章"},"text":{"zh":"执照执有者或受执照持有者委托的经营者，如发生下列情况，局有权在规定期限内收回或吊销执照：\n1、违反执照规定的纪律；\n2、没获得局批准私自转让企业；\n3、出售执照。"}},{"id":"MM-H067-A20","no":20,"noLabel":{"zh":"第20条"},"chapter":{"zh":"第十章"},"text":{"zh":"如发生下列情况之一，执照即自行废除：\n1、执照到期；\n2、执照被限期收回；\n3、执照被吊销；\n4、执照持有者交回执照。\n第十章 上诉"}},{"id":"MM-H067-A21","no":21,"noLabel":{"zh":"第21条"},"chapter":{"zh":"第十章"},"text":{"zh":"如对局有关执照处理命令或决定不满，可在命令或决定下达日起六十天内向部长提出申诉。"}},{"id":"MM-H067-A22","no":22,"noLabel":{"zh":"第22条"},"chapter":{"zh":"第十一章"},"text":{"zh":"部长的决定为最终裁决。\n第十一章 禁止"}},{"id":"MM-H067-A23","no":23,"noLabel":{"zh":"第23条"},"chapter":{"zh":"第十一章"},"text":{"zh":"如不按第十六条第 1 款规定取得执照者，任何人均不得从事旅馆和旅游业。"}},{"id":"MM-H067-A24","no":24,"noLabel":{"zh":"第24条"},"chapter":{"zh":"第十一章"},"text":{"zh":"执照持有者在没有得到局批准前不得转让经营企业或出售执照。"}},{"id":"MM-H067-A25","no":25,"noLabel":{"zh":"第25条"},"chapter":{"zh":"第十二章"},"text":{"zh":"执照持有者或受执照持有者委托的经营者：\n1、不准违反执照有关规定；\n2、不准违反第十八条规定的义务；\n3、不准违反部或局颁布的命令或规定所指出的禁例。\n第十二章 惩处"}},{"id":"MM-H067-A26","no":26,"noLabel":{"zh":"第26条"},"chapter":{"zh":"第十二章"},"text":{"zh":"1、如有违反第二十三条者，经查证后，将被判处最高三年的徒刑，或最高达 5 万缅元的罚款，或二者并罚；\n2、根据第一款被惩罚者如继续违反第二十三条规定者，对其继续违法期间，每天处以五千缅元的罚款。"}},{"id":"MM-H067-A27","no":27,"noLabel":{"zh":"第27条"},"chapter":{"zh":"第十二章"},"text":{"zh":"执照持有者如违反第二十四条某项规定，经查证属实，将处以最高为五万缅元的罚款。"}},{"id":"MM-H067-A28","no":28,"noLabel":{"zh":"第28条"},"chapter":{"zh":"第十三章"},"text":{"zh":"执照持有者或者受执照持有者委托的经营者，如果违反第二十五条中的某项规定的，经查证属实，将处以最高为五千缅元的罚款。\n第十三章 其他"}},{"id":"MM-H067-A29","no":29,"noLabel":{"zh":"第29条"},"chapter":{"zh":"第十三章"},"text":{"zh":"根据缅甸旅游法颁布的旅游业执照在规定期限内。持续有效"}},{"id":"MM-H067-A30","no":30,"noLabel":{"zh":"第30条"},"chapter":{"zh":"第十三章"},"text":{"zh":"根据本法废止的缅甸旅游法制定的相关条例、命令、指示，如不违反本法者一律继续有效。"}},{"id":"MM-H067-A31","no":31,"noLabel":{"zh":"第31条"},"chapter":{"zh":"第十三章"},"text":{"zh":"为能具体执行本法\n1、部在征得政府同意后可以发布必要的条例和细则；\n2、部或局可发布必要的命令、通令和指示。"}},{"id":"MM-H067-A32","no":32,"noLabel":{"zh":"第32条"},"chapter":{"zh":"第十三章"},"text":{"zh":"本法自公布之日起《缅甸旅游法》（93/13）即废止。"}}],"pack":"mm-p04","rebuiltFrom":"原为单条全文，2026-10-24 按条号标记重新切分（拼接无损校验通过）"};
  FT["MM-H068"] = {"id":"MM-H068","coverage":"full","language":"zh","sourceName":"缅甸官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":1,"structureMode":"WHOLE","title":{"zh":"议会管理小组法 2018","en":"Law on the Hluttaw Management Committee 2018","orig":"议会管理小组法 2018","vi":"Luật về Ủy ban Quản lý Hluttaw năm 2018","th":"พระราชบัญญัติว่าด้วยคณะกรรมการบริหารรัฐสภา ค.ศ. 2018","id":"Undang-Undang tentang Komite Pengelolaan Hluttaw Tahun 2018","ms":"Akta mengenai Jawatankuasa Pengurusan Hluttaw 2018"},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"缅甸官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"MM","countryName":"缅甸","layer":"intl","articles":[{"id":"MM-H068-A1","no":1,"noLabel":{"zh":"第 1 条"},"text":{"zh":"“一带一路”法律查明     第 1 卷 ·182· 缅甸联邦共和国议会管理小组法 a （2018 年缅甸联邦共和国议会第 4 号法令） 缅历 1379 年 11 月 23 日 2 0 1 8年2月8日联邦议会颁布了本法。\n第一章  名称及释义\n第1条  这部法律的名称为缅甸议会管理小组法。\n第2条  这部法律中包含的词语具有如下释义：\n（一） 宪法： 指缅甸联邦宪法。\n（二） 议会： 指根据宪法建立的缅甸联邦议会。\n（三） 人民院： 指依据宪法建立的人民院。\n（四） 民族院： 指依据宪法建立的民族院。\n（五） 省或邦议院： 指根据宪法建立的省或邦议院。\n（六） 议会： 指联邦议会、 人民院、 民族院、 省或邦议院。\n（七） 议会管理小组： 指根据本法建立的议会管理小组。\n（八） 主席： 指担任联邦议会主席的民族院议长或人民院议长。\n（九） 副主席： 指担任联邦议会副主席的民族副院议长或人民院副议长。\n（十） 议长： 指各院的主席。\n（十一） 议员： 指包括议会各院的议长、 副议长、 秘书等在内的各位议员。\n（十二） 议会管理小组办公室： 指根据本法建立的缅甸议会管理小组办公室。\n（十三） 办公室主任： 指议会管理小组办公室主任。\n（十四） 会议： 指议会小组的会议。\n* 本文译者： 商雨晴， 系北京外国语大学亚非学院硕士研究生。\n* ·183· 缅甸联邦共和国议会管理小组法第二章  目标第 3 条  本法律目标如下：\n（一） 为各议院办事方法正确可靠， 办事能力稳步提升而与相关组织共同合作努力；\n（二） 为议会之间交流经验与水平提升而共同合作努力；\n（三） 与制定国际法的各组织、 目标相同的各国家组织、 政府组织和非政府组织共同努力；\n（四） 与包括国际议会组织和东盟议会在内的各国家和地区内的相关议会组织共同努力。\n第三章  议会组成、 任期和会议举行组成\n第4条  缅甸联邦议会的议会管理小组由下列人员组成：\n（一） 议长     主席 （联邦议会）\n（二） 议长     副主席 （民族议院或人民议院）\n（三） 副议长     议员 （民族议院或人民议院）\n（四） 众议长     众议员 （省邦议院）\n（五） 副议长     秘书 （联邦议会）\n第5条  联邦议会办公室的司长按照职位高低任命为议会管理小组办公室主任。\n任期\n第6条  议会管理小组的任期和联邦议会的任期相同。\n会议举办\n第7条\n（一） 小组会议在1 年内需至少举办 1 次。\n“一带一路”法律查明     第 1 卷 ·184·\n（二） 如主席认为有必要召开特殊会议， 或半数以上小组成员认为有必要召开特殊会议， 则主席可召集成员召开特殊会议。\n（三） 会议须在主席规定的日期、 时间、 地点召开。\n（四） 会议召开时， 有超过半数以上的成员参会， 则会议有效。\n（五） 当作为议员的省邦议会主席无法参加会议时， 副主席可作为其代表代替出席。\n（六） 若会议未能成功举办， 则主席可要求各成员将提案或建议以书面形式上交。\n（七） 办公室主任需在议会管理小组会议中作为仪式负责人参与。\n第四章  议会管理小组的职责\n第8条  议会组织的职责包括下述几点：\n（一） 实现本法的目标。\n（二） 共同商议包括宪法颁布、 议会相关法修订及法律审议通过等相关事务。\n（三） 协商联邦与各省邦地区联络交流相关事务。\n（四） 为议会管理小组的发展、 议会代表与其他工作人员的能力提升进行讨论商议、 派遣相关人员参加国内国外培训班、 研讨会及会议等。\n（五） 议会小组如需要相关组织可按照需要进行组建。\n（六） 负责进行包括议会组织和国际上的议会组织、 东盟议会在内的国际上和地区性质的组织机构间进行交往联络； 向小组人员、 相关组织、 国民传达这些组织机构的宗旨、 决议等事宜。\n（七） 向国际上的议会组织告知缅甸联邦议会的发展情况。\n第9条  议会管理小组的秘书：\n（一） 负责进行举行会议等相关安排。\n（二） 将管理小组的工作情况在会议上进行汇报。\n（三） 协助制定议会管理小组的年度计划并在会议上进行汇报。\n（四） 执行主席交由的其他任务。\n第五章  小组成员的权利和责任第1 0条  小组成员应为实现议会管理小组的目标和职责而努力。\n第1 1条  小组成员应执行议会的协商决议， 执行决议的情况需向议会管理小组进行上报。\n第1 2条  小组成员在会议中遇到与议会相关的困难时， 有权为能与其他成员共同进 ·185· 缅甸联邦共和国议会管理小组法行商议提出申请。\n第1 3条  小组成员有权利知晓管理小组发布的消息。\n第六章  其他第1 4条  本法未颁布前成立的缅甸联邦议会相关小组依据本法更名为缅甸议会管理小组。\n第1 5条  议会管理小组秘书需将议会管理小组的工作报告上报联邦议会， 也需提交给其他相关议会。\n第1 6条  如省或邦的议会主席认为第 15 条提到的报告需在省或邦中的议会中提交， 则可选在其最近的会议中进行提交。\n第1 7条  议会管理小组的工作和管理事宜全权由议会办公室进行管理。\n第1 8条  议会管理小组的经费及支出方式由议会办公室负责管理和支出。\n根据缅甸联邦共和国宪法， 我签署该法令。\n廷觉 （印） 缅甸联邦共和国总统"}}],"pack":"mm-p04"};
})(typeof window !== 'undefined' ? window : globalThis);
